SELECT id, ledger_id, name, type, balance, created_at, updated_at
FROM accounts
WHERE ledger_id = #{ledgerId}

SELECT id, ledger_id, name, type, balance, created_at, updated_at
FROM accounts
WHERE id = #{id}

mapper.update:
UPDATE accounts
